  .option-item.selected {
    background: rgba(245, 234, 220, 0.2);
    font-weight: 600;
    opacity: 1;
    box-shadow: 0 2px 8px rgba(139, 69, 19, 0.08); /* 复古阴影 */
  }
  .display {
    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px solid rgba(188, 143, 143, 0.1);
    font-size: 12px;
    opacity: .6;
    min-height: 18px;
    text-align: right;
    font-style: italic; /* 斜体强化复古感 */
    color: #6b4226;
  }
</style>
</head>
<body>

<div class="panel">
  <div class="header">Select Path</div>
  <ul class="option-list">
    <li class="option-item" onclick="pick(this)">$1</li>
    <li class="option-item" onclick="pick(this)">$2</li>
    <li class="option-item" onclick="pick(this)">$3</li>
    <li class="option-item" onclick="pick(this)">$4</li>
    <li class="option-item" onclick="pick(this)">$5</li>
  </ul>
  <div class="display" id="display">Waiting for input...</div>
</div>

<script>
  let last = null;
  function pick(el) {
    // 1. 获取元素文本
    let txt = el.innerText || el.textContent;

    // 2. 切换选中样式
    last?.classList.remove('selected');
    el.classList.add('selected');
    last = el;

    // 3. 更新本地显示
    document.getElementById('display').innerText = txt;

    // 4. 尝试填充到目标输入框（去掉try/catch，显示错误）
    console.log('尝试填充文本：', txt); // 调试日志
    try {
      // 优先找当前页面的输入框（方便测试），再找父页面
      const ta = document.querySelector('#send_textarea') || window.parent?.document?.querySelector('#send_textarea');

      if (!ta) {
        console.error('未找到目标输入框！请检查id是否为send_textarea');
        document.getElementById('display').innerText = '错误：未找到输入框';
        return;
      }

      // 填充文本并触发完整的input事件（兼容所有浏览器）
      ta.value = txt;
      ta.dispatchEvent(new Event('input', { 
        bubbles: true, 
        cancelable: true 
      }));
      console.log('文本填充成功！目标元素：', ta);
    } catch(e) {
      // 打印错误，方便定位
      console.error('填充文本失败：', e.message);
      document.getElementById('display').innerText = `失败：${e.message}`;
    }
  }
</script>
</body>
</html>
